l bg-white p-5 sm:p-7"><p class="text-xs uppercase tracking-widest text-lime-700">{{ ucfirst($listing->condition) }} · {{ $listing->location }}</p><h1 class="mt-2 text-2xl font-medium tracking-tight text-gray-900 sm:text-3xl">{{ $listing->title }}</h1><p class="mt-4 text-3xl font-semibold text-gray-900">K{{ number_format((float)$listing->price,2) }}</p><div class="my-6 border-t border-gray-100"></div><h2 class="text-sm font-semibold text-gray-900">Item description</h2><p class="mt-2 whitespace-pre-line text-sm leading-7 text-gray-600">{{ $listing->description }}</p><div class="my-6 border-t border-gray-100"></div><a href="{{ route('seller.show',$listing->user) }}" class="flex items-center gap-3 rounded-xl bg-gray-50 p-3 hover:bg-gray-100">@if($listing->user?->profile_photo_url)<img src="{{ $listing->user->profile_photo_url }}" class="h-12 w-12 rounded-full object-cover" alt="">@else<span class="grid h-12 w-12 place-items-center rounded-full bg-lime-100 text-lg">{{ strtoupper(substr($listing->user?->name ?? 'S',0,1)) }}</span>@endif<div class="min-w-0 flex-1"><p class="text-sm font-medium text-gray-900">{{ $listing->user?->name ?? 'MarketPG seller' }}</p><p class="mt-1 text-xs text-gray-500">{{ $sellerSales }} completed sales · {{ $listing->user?->seller_rank ?? 'New Seller' }}</p></div><span class="text-sm text-lime-700">View seller →</span></a><a href="/login" class="market-button mt-5 block bg-lime-400 px-5 py-3 text-center text-sm font-semibold text-gray-950 hover:bg-lime-300">Sign in to contact seller / buy</a><p class="mt-3 text-center text-xs text-gray-400">Keep transactions and communications within MarketPG.</p></section></div>@if($sellerListings->isNotEmpty())<section class="mt-12"><h2 class="text-xl font-medium text-gray-900">More from this seller</h2><div class="mt-4 grid grid-cols-2 gap-3 sm:grid-cols-4">@foreach($sellerListings as $item)<a href="{{ route('listing.show',$item) }}" class="market-card overflow-hidden rounded-xl bg-white">@if($item->image_url)<img src="{{ $item->image_url }}" class="aspect-square w-full object-cover" alt="{{ $item->title }}">@else<div class="aspect-square bg-gray-100"></div>@endif<div class="p-3"><p class="line-clamp-2 text-sm">{{ $item->title }}</p><p class="mt-2 font-semibold">K{{ number_format((float)$item->price,2) }}</p></div></a>@endforeach</div></section>@endif</main><script>function setPhoto(src){document.getElementById('heroImage').src=src;document.getElementById('heroImage').style.display='block';document.getElementById('emptyPhoto').classList.add('hidden')}</script><script>
(function(){function setTheme(theme){document.documentElement.dataset.theme=theme;try{localStorage.setItem('marketpg_theme',theme);}catch(e){}document.querySelectorAll('[data-marketpg-theme-toggle]').forEach(function(button){button.textContent=theme==='dark'?'☀ Light':'☾ Dark';button.setAttribute('aria-label',theme==='dark'?'Switch to light mode':'Switch to dark mode');button.setAttribute('title',theme==='dark'?'Switch to light mode':'Switch to dark mode');});}
window.marketpgToggleTheme=function(){setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');};
document.addEventListener('DOMContentLoaded',function(){setTheme(document.documentElement.dataset.theme||'light');});
})();
</script></body></html>